def retry(fn, attempts=5, base=0.1, cap=2.0, retryable=(TimeoutError,), sleep=None, jitter=lambda d: d):
    for n in range(attempts):
        try:
            return fn()
        except retryable:
            if n == attempts - 1:
                raise
            sleep(jitter(min(cap, base * 2 ** n)))

sleeps = []
state = {"calls": 0}

def flaky():
    state["calls"] += 1
    if state["calls"] < 4:
        raise TimeoutError("slow")
    return "ok"

print(retry(flaky, sleep=sleeps.append), state["calls"], sleeps)

def bad():
    state["calls"] += 1
    raise ValueError("client bug")

state["calls"] = 0
try:
    retry(bad, sleep=sleeps.append)
except ValueError:
    print("not retried, calls =", state["calls"])

state["calls"] = -100
try:
    retry(flaky, attempts=2, sleep=lambda d: None)
except TimeoutError:
    print("gave up")
